import React from "react";
// import React, { useState } from "react";
import Banner from "./Banner";
// import api from "../api";
import '../styles/main.css';

export default function Admissions() {
  // const [form, setForm] = useState({
  //   studentName: "",
  //   parentName: "",
  //   classApplied: "",
  //   age: "",
  //   phone: "",
  //   email: "",
  //   address: ""
  // });

  // const [status, setStatus] = useState("");

  // const change = (e) =>
  //   setForm((f) => ({ ...f, [e.target.name]: e.target.value }));

  // const submit = async (e) => {
  //   e.preventDefault();
  //   setStatus("Submitting...");
  //   try {
  //     await api.post("/admissions", form);
  //     setStatus("Application submitted successfully!");
  //     setForm({
  //       studentName: "",
  //       parentName: "",
  //       classApplied: "",
  //       age: "",
  //       phone: "",
  //       email: "",
  //       address: ""
  //     });
  //   } catch (err) {
  //     console.error(err);
  //     setStatus("Submission failed. Please try again.");
  //   }
  // };

  return (
    <>
    <Banner /> {/* ✅ added banner */}
    <div className="admissions-page">
      <div className="left-column">
        <h2>Admissions</h2>
        <div className="info-box">
          <p>Application Form</p>
          <p>Apply Online</p>
          <p>Fee Structure</p>
        </div>
      </div>

      <div className="right-column">
        <h2>The Procedure</h2>
        <p>
          We appreciate your interest in us! We believe in quality rather than just quantity and subscribe to good companionship, virtue & nurturing environment for making creative and street smart kids.
        </p>


        <div className="apply-button-container">
          <button
            onClick={() => window.open("/admission-form", "_blank")}
            className="apply-btn"
          >
            Apply by clicking here
          </button>
        </div>


        <p>
          <strong>Regarding admission & withdrawal:</strong><br />
          The Principal reserves the rights to refuse admission to anybody without furnishing any reason.<br />
          Parent would have to deposit all the required documents and admission fees within a week of passing the admission test.<br />
          Other documents like birth certificate, T.C. have to be submitted within one month after the admission.<br />
          In case the student stops attending school without prior information, his/her name will be struck off the school rolls after 15 continuous days of absence. Re-admission will be granted only after seeking written permission from the principal by depositing Rs. 1000/- as re-admission fees.
        </p>

        <h3>Fee Structure (Session 2024–25)</h3>
        <table className="fee-table">
          <thead>
            <tr>
              <th>Particular</th>
              <th>Details</th>
              <th>Classes</th>
            </tr>
          </thead>
          <tbody>
            <tr><td>Registration Fees</td><td>Charged at Admission</td><td>₹1000</td></tr>
            <tr><td>Admission Fees</td><td>Charged at Admission/Re-admission</td><td>₹10000</td></tr>
            <tr><td>Composite Monthly Fees</td><td>Before 15th of every month</td><td>₹1970–₹3700</td></tr>
          </tbody>
        </table>

        <h3>Transportation Charges</h3>
        <ul>
          <li>Up to 4 Km – ₹750/month</li>
          <li>Up to 6 Km – ₹950/month</li>
          <li>Up to 8 Km – ₹1250/month</li>
          <li>Up to 10 Km – ₹1450/month</li>
        </ul>

        <h3>Instructions for Payment of Fee</h3>
        <ul>
          <li>Advance fee on Half yearly basis accepted with rebate of 3%.</li>
          <li>Advance fee on Annual basis accepted with rebate of 7%.</li>
          <li>Fees to be paid by 15th of every month.</li>
          <li>Fine ₹50 after due date, name struck off after 3 months.</li>
          <li>Fees can be paid online via NEFT.</li>
        </ul>

        <h4>Bank Details:</h4>
        <p>
          Bank Name: INDIAN BANK<br />
          Account No.: 50285356754<br />
          Branch: Delhi Chungi<br />
          IFSC: IDIB000M685
        </p>

        {/* <hr /> */}

        {/* <h3>Online Application Form</h3>
        <form className="admission-form" onSubmit={submit}>
          <input
            name="studentName"
            placeholder="Student Name"
            value={form.studentName}
            onChange={change}
            required
          />
          <input
            name="parentName"
            placeholder="Parent Name"
            value={form.parentName}
            onChange={change}
            required
          />
          <input
            name="classApplied"
            placeholder="Class Applied"
            value={form.classApplied}
            onChange={change}
            required
          />
          <input
            name="age"
            placeholder="Age"
            value={form.age}
            onChange={change}
            required
          />
          <input
            name="phone"
            placeholder="Phone"
            value={form.phone}
            onChange={change}
            required
          />
          <input
            name="email"
            placeholder="Email"
            value={form.email}
            onChange={change}
            required
          />
          <textarea
            name="address"
            placeholder="Address"
            value={form.address}
            onChange={change}
            required
          />
          <button type="submit">Apply Now</button>
          <div className="status">{status}</div>
        </form> */}
      </div>
    </div>
    </>
  );
}
